-- English WORMHOLE defaults; preserve operator-edited configuration and prompt history.
CREATE TEMP TABLE wormhole_english_tools(key text,description text,schema jsonb,agents jsonb) ON COMMIT DROP;
INSERT INTO wormhole_english_tools VALUES
('add_company_scope','Add the domain name/IP/CIDR/ICP registration/enterprise keywords to a company''s [Asset Scope] - the domain name, network and ICP will automatically claim the hit assets, and the keywords are only provided to the Agent as a scope prompt.
The company name is unique: If company does not exist, create a new one, and if it already exists, reuse it (only merge the scope).
Scope is one line at a time, and the system automatically identifies: root domain name / URL / single IP / CIDR network segment / ICP registration / enterprise keywords.
Be sure to provide reason with the attribution basis (whois/certificate/ASN, etc.).
Guardrails: Reject naked TLDs and overly wide network segments (IPv4 prefixes must be /16-/32, IPv6 prefixes must be /32-/128), illegal lines will be skipped and returned in errors.','{"properties": {"company": {"description": "Company name (create if it does not exist, reuse if it exists; the name is unique)", "type": "string"}, "logo": {"description": "Company icon URL (optional; only valid when creating a new company)", "type": "string"}, "reason": {"description": "Basis of attribution (evidence/source), must be filled in", "type": "string"}, "scope": {"description": "Asset scope, one line per line: domain name / URL / IP / CIDR / ICP filing / enterprise keywords", "type": "string"}}, "required": ["company", "scope"], "type": "object"}'::jsonb,'["mainagent", "planner", "auto"]'::jsonb),
('add_hint','Hook the human/master agent''s strategic prompts to the exploration graph and the planner will read it the next time it generates an intent.
★Priority batch: Put multiple hints into the hints array and submit them at once (saving round trips than calling them one by one). Returns an array of ids, in the same length and order as hints (failure item id=0, see errors for details). For a single item, hints are omitted and given directly to the top-level text.','{"properties": {"asset_ids": {"description": "Anchored asset id (optional, 0/1/multiple)", "items": {"type": "integer"}, "type": "array"}, "hints": {"description": "[Use this first] The prompt array to be added will be processed in order. Each element field is the same as the top-level field below (text/asset_ids/traffic_refs). The returned ids are of the same length and order as this array.", "items": {"properties": {"asset_ids": {"items": {"type": "integer"}, "type": "array"}, "text": {"description": "Prompt content", "type": "string"}, "traffic_refs": {"description": "Optional: The traffic references that have been verified and correspond to the specific vulnerabilities in this tip are kept in order; after handover, report_finding can pass evidence_hint_id carrying these references.", "items": {"properties": {"note": {"description": "What conclusion does this flow support?", "type": "string"}, "role": {"description": "baseline / proof / verification / supporting", "type": "string"}, "traffic_id": {"description": "Real Traffic ID", "type": "string"}}, "required": ["traffic_id"], "type": "object"}, "type": "array"}}, "type": "object"}, "type": "array"}, "text": {"description": "[Single item] Prompt content, such as ''Focus on mining post-certification interfaces''", "type": "string"}, "traffic_refs": {"description": "Optional: The traffic references that have been verified and correspond to the specific vulnerabilities in this tip are kept in order; after handover, report_finding can pass evidence_hint_id carrying these references.", "items": {"properties": {"note": {"description": "What conclusion does this flow support?", "type": "string"}, "role": {"description": "baseline / proof / verification / supporting", "type": "string"}, "traffic_id": {"description": "Real Traffic ID", "type": "string"}}, "required": ["traffic_id"], "type": "object"}, "type": "array"}}, "type": "object"}'::jsonb,'["mainagent"]'::jsonb),
('add_intent','Generate [exploration direction] and write it into frontier, and connect it to the exploration link. The intention is an open exploration direction, not a fixed type - use a summary to freely describe what to explore/verify/exploit.
★Priority batch: Multiple new directions filtered out in one round are put into the intents array and submitted at once (saving round trips than calling one by one). Returns an array of ids, in the same length and order as intents (failure item id=0, see errors for details). For a single item, the intents are omitted and given directly to the top-level summary.','{"properties": {"asset_ids": {"description": "[Target asset ID] to be tested/attacked in this direction (**try to pass**, 0/1/multiple; it is the asset ID returned by list_assets, not the exploration node ID): which assets (site/interface/parameter/host, etc.) this exploration direction targets. As long as the direction revolves around certain specific assets, it must be uploaded - it is a structured markup of \"what goals are this exploration targeting?\" and is used to cover duplication and connect intentions to asset links. Only leave this blank if it is pure global reconnaissance and there really are no specific target assets.", "items": {"type": "integer"}, "type": "array"}, "intents": {"description": "[Use this first] The array of exploration directions to be added is processed in order. Each element field is the same as the top-level field below (summary/asset_ids/parent_ids/priority). The returned ids are of the same length and order as this array.", "items": {"type": "object"}, "type": "array"}, "parent_ids": {"description": "Upstream anchor id (optional, 0/1/multiple): This direction is derived from the [confirmed facts/findings]. **Only existing fact/finding node ids can be filled in, not intentions/goals/prompts** - Intentions must be anchored on confirmed knowledge, driven by discovery rather than planning out of thin air. If multiple facts jointly generate a new intention, please pass multiple; please leave the top-level new reconnaissance direction blank (it will automatically be linked to the origin fact of the task).", "items": {"type": "integer"}, "type": "array"}, "priority": {"description": "Priority 0-10, default 5", "type": "integer"}, "summary": {"description": "[Single article] Describe this exploration direction in one sentence: what to do + why. Just write the direction clearly and it does not depend on the asset ID.", "type": "string"}}, "type": "object"}'::jsonb,'["mainagent", "planner"]'::jsonb),
('add_task_hint','Inject strategic hints into the specified task (the planner of the task will read it when generating the intention in the next round).
★Batch priority: Put multiple hints into the hints array and submit them at once (return the ids array, in the same length and order as hints, and the failed item id=0); for a single hint, omit hints and send it directly to the top-level text.','{"properties": {"asset_ids": {"description": "Anchored asset id (optional, 0/1/multiple; asset id within this task)", "items": {"type": "integer"}, "type": "array"}, "hints": {"description": "[Use this first] Prompt array, each element field is the same as the top level (text/asset_ids/traffic_refs).", "items": {"properties": {"asset_ids": {"items": {"type": "integer"}, "type": "array"}, "text": {"description": "Prompt content", "type": "string"}, "traffic_refs": {"description": "Optional: The traffic references that have been verified and correspond to the specific vulnerabilities in this tip are kept in order; after handover, report_finding can pass evidence_hint_id carrying these references.", "items": {"properties": {"note": {"description": "What conclusion does this flow support?", "type": "string"}, "role": {"description": "baseline / proof / verification / supporting", "type": "string"}, "traffic_id": {"description": "Real Traffic ID", "type": "string"}}, "required": ["traffic_id"], "type": "object"}, "type": "array"}}, "type": "object"}, "type": "array"}, "task_id": {"description": "Task id", "type": "string"}, "text": {"description": "[Single] Prompt content", "type": "string"}, "traffic_refs": {"description": "Optional: The traffic references that have been verified and correspond to the specific vulnerabilities in this tip are kept in order; after handover, report_finding can pass evidence_hint_id carrying these references.", "items": {"properties": {"note": {"description": "What conclusion does this flow support?", "type": "string"}, "role": {"description": "baseline / proof / verification / supporting", "type": "string"}, "traffic_id": {"description": "Real Traffic ID", "type": "string"}}, "required": ["traffic_id"], "type": "object"}, "type": "array"}}, "required": ["task_id"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('add_task_scope','Add the test scope to [this task] - this is the authorization boundary of this task and also the denominator of asset test coverage.
kind supports: company (assets under the entire company''s name) / root_domain (the entire root domain, including all subdomains) / subdomain (a single precise subdomain) / ip / cidr / icp / keyword.
Description: Hosts encountered by workers one by one will be [automatically] added to the scope (precise subdomain) by the system; this tool is used to [active expansion] - include the entire root domain/entire company, or additionally specify a certain subdomain/IP.
value: company passes the company name or id (the company must already exist); root_domain/subdomain passes the domain name; ip/cidr passes the IP or network segment; icp/keyword passes the registration number or company keyword.
Be sure to give reason a basis (auditable). Use the entries array for multiple entries.','{"properties": {"entries": {"description": "Batch: [{kind, value}]. kind∈company/root_domain/subdomain/ip/cidr/icp/keyword.", "items": {"type": "object"}, "type": "array"}, "kind": {"description": "[Single entry] company/root_domain/subdomain/ip/cidr/icp/keyword", "type": "string"}, "reason": {"description": "Basis for joining (for audit), be sure to fill in", "type": "string"}, "value": {"description": "[Single entry] Company name or id / domain name / IP / CIDR / ICP / keyword", "type": "string"}}, "type": "object"}'::jsonb,'["mainagent", "planner"]'::jsonb),
('bind_finding_traffic','Patch verified real HTTP traffic for registered vulnerabilities. finding_id uses an independent vulnerability record ID; do not pass the exploration node ID. All references in the same batch succeed or all fail. Repeated references will not cover existing instructions. Patching will mark existing reports for update; do not re-detect or re-create vulnerabilities for patching.','{"properties": {"finding_id": {"description": "Individual vulnerability record ID, read from the finding_id field of list_task_findings/get_task_node_detail", "type": "string"}, "traffic_refs": {"description": "Optional: The traffic references that have been verified and correspond to the specific vulnerabilities in this tip are kept in order; after handover, report_finding can pass evidence_hint_id carrying these references.", "items": {"properties": {"note": {"description": "What conclusion does this flow support?", "type": "string"}, "role": {"description": "baseline / proof / verification / supporting", "type": "string"}, "traffic_id": {"description": "Real Traffic ID", "type": "string"}}, "required": ["traffic_id"], "type": "object"}, "type": "array"}}, "required": ["finding_id", "traffic_refs"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('create_custom_tool','[Important] When installing some tools that are not available on the platform, call this tool to put the installed tools into the platform so that the platform can call it! Create a custom tool (shell/command/script/http). shell=bash environment declaration, only key+description+agents, no exec/schema required.','{"properties": {"agents": {"description": "Binding agent key (optional)", "items": {"type": "string"}, "type": "array"}, "deferred": {"description": "Whether to delay (the shell type is invalid; only uncommon tools of command/script/http are enabled)", "type": "boolean"}, "description": {"description": "Description sent to model", "type": "string"}, "enabled": {"description": "Whether to enable (default true)", "type": "boolean"}, "exec": {"description": "Execution specifications (not required for shell type): command→{command}; script→{code}; http→{method,url,headers,body,proxy,use_recording_proxy}", "type": "object"}, "key": {"description": "Tool key (begins with lowercase letter, letter/number/underline)", "type": "string"}, "kind": {"description": "shell | command | script (Python only) | http. shell=bash environment statement (only informs the model that the tool can be called directly in bash without exec/schema); the other three require exec", "type": "string"}, "schema": {"description": "Parameter JSON-Schema (shell/command/script can be left blank; http is required and must contain properties)", "type": "object"}}, "required": ["key", "kind"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('create_mcp','Create an MCP server (stdio/http/sse). After creation, its tools need to be authorized according to agent visibility.','{"properties": {"args": {"description": "Command parameter array\nStart command for", "items": {"type": "string"}, "type": "array"}, "command": {"description": "stdio startup command (such as npx)", "type": "string"}, "enabled": {"description": "Whether to enable (default true)", "type": "boolean"}, "env": {"description": "Environment variable {KEY:VALUE}", "type": "object"}, "insecure": {"description": "http: Skip TLS certificate verification (set to true when self-signing the certificate, default to false)", "type": "boolean"}, "name": {"description": "MCP server name", "type": "string"}, "transport": {"description": "stdio | http / sse", "type": "string"}, "url": {"description": "URL for http/sse", "type": "string"}}, "required": ["name", "transport"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('create_skill','Create a new skill (write SKILL.md, agentskills.io specification). name lowercase letters/numbers/hyphens.','{"properties": {"description": {"description": "Skill description (required, describe what it does/when to use it)", "type": "string"}, "instructions": {"description": "Markdown text description (optional)", "type": "string"}, "name": {"description": "Skill name (begins with a lowercase letter, letters/numbers/hyphens)", "type": "string"}}, "required": ["name", "description"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('delete_assets_by_host','Accurately delete assets by host: delete the domain name/subdomain name of the host, as well as the services and endpoints under it.
host matches exactly (lowercase, remove spaces), not fuzzy/wildcarding.
Passing the root domain name (such as example.com) will also delete its subdomain name and its services/interfaces; passing the subdomain name (such as a.example.com) or IP will only delete the host itself and its services/interfaces.
⚠️ Hard deletion, affects the global asset library (shared across tasks), and cannot be undone.','{"properties": {"host": {"description": "Host to be deleted: domain name/subdomain name/IP. An exact match like example.com or a.example.com or 1.2.3.4", "type": "string"}}, "required": ["host"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('expand_digest','Expand a cold digest: Return a compact list of its collapsed members (id/summary/state/confidence), with the same shape as the overview recent_facts/recent_done_intents. To request complete details/evidence of a piece of information, use node_detail(member_id).','{"properties": {"id": {"description": "digest node id (from overview cold_digests)", "type": "integer"}}, "required": ["id"], "type": "object"}'::jsonb,'["mainagent", "planner"]'::jsonb),
('get_finding_traffic','Read the real traffic evidence that the vulnerability has been bound to, without relying on the capture switch. finding_id uses the individual vulnerability record ID returned by report_finding JSON (not the discovery node ID of the first row). Do not pass binding_id to get the list and version; an empty list is normal. For non-HTTP vulnerabilities such as TCP or when they are not collected, reports can still be written based on text/command evidence without forcing binding. When there is binding, read the text in sections according to binding_id, side(request/response), and offset. When writing the report, the read version is passed to update_finding_report as evidence_version, and the latter''s finding_id still uses the exploration node ID.','{"properties": {"binding_id": {"description": "Binding ID in the list, if omitted, the list will be returned", "type": "string"}, "finding_id": {"description": "Independent vulnerability record ID", "type": "string"}, "length": {"type": "integer"}, "offset": {"type": "integer"}, "side": {"description": "request or response, default response", "type": "string"}}, "required": ["finding_id"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('get_task_graph','Read the exploration graph overview of the specified task (same as graph_overview: asset count/frontier/discovery/coverage, etc.), specify the task with task_id.','{"properties": {"task_id": {"description": "Task id", "type": "string"}}, "required": ["task_id"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('get_task_node_detail','Read the complete content of an exploration graph node in the specified task (discovery/facts/intentions/goals: summary + details/evidence/PoC). id is the exploration node id (such as the id returned by report_finding, or the id in list_task_findings). Use it to obtain complete evidence of the vulnerability before writing a vulnerability report.','{"properties": {"id": {"description": "Exploration graph node id (non-asset id)", "type": "integer"}, "task_id": {"description": "Task id", "type": "string"}}, "required": ["task_id", "id"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('get_task_worker_trace','View the execution process of a certain work (intention) in the specified task: get_task_worker_trace(task_id, intent_id) to view the step summary; then add step_ids=[...] to get the complete content of those steps (up to 5 at a time, only the first 5 will be returned in multi-pass).','{"properties": {"intent_id": {"description": "Intent id (work in this task)", "type": "integer"}, "step_ids": {"description": "Optional: Step ids to get the complete content (up to 5 at a time, only the first 5 are returned for multi-pass, and the rest are listed in omitted_step_ids)", "items": {"type": "integer"}, "type": "array"}, "task_id": {"description": "Task id", "type": "string"}}, "required": ["task_id", "intent_id"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('get_worker_output','Get the final output conclusion of this task or an intention (work) directly related to the task. The associated task results have source_task_id/inherited=true and are read-only. A normal end returns its summary; a stopped/abnormal work returns its last output up to the time of abort.','{"properties": {"intent_id": {"description": "Intent id (= work handle)", "type": "integer"}}, "required": ["intent_id"], "type": "object"}'::jsonb,'["mainagent", "planner"]'::jsonb),
('get_worker_trace','View the [execution process] of a certain intention (work) (different from get_worker_output which only gives the final conclusion). Three usages:
① Only pass intent_id → Return the summary stream of each step of the work (summary ≤ 100 words, including step_id; only the action outline, not including complete output);
② intent_id + q → only returns the summary of steps that hit the keyword (search in both summary and complete output; still only gives summary, use ③ to see the content);
③ intent_id + step_ids → Return the complete content (detail) of these steps; a maximum of 5 can be taken at a time. If the number exceeds 5, only the first 5 will be returned and the untaken ones will be notified in notice/omitted_step_ids.
Typical process: First ①/② locate the step_id of the suspicious step, and then use ③ to obtain its complete output. There is no thinking step. Supports historical traces directly associated with tasks; the results have source_task_id/inherited=true and are read-only.','{"properties": {"intent_id": {"description": "Intent id (= work handle)", "type": "integer"}, "limit": {"description": "Return limit for summary streams/retrievals (optional)", "type": "integer"}, "q": {"description": "Keyword: only return summary/full output of steps that hit it (optional; mutually exclusive with step_ids)", "type": "string"}, "step_ids": {"description": "To get the step_id of the complete content (returned from ①/②; up to 5 are taken at a time, only the first 5 are returned for multi-pass, and the rest are listed in omitted_step_ids)", "items": {"type": "integer"}, "type": "array"}}, "required": ["intent_id"], "type": "object"}'::jsonb,'["mainagent", "planner", "worker"]'::jsonb),
('goal_met','[End the entire mission immediately] - Only call it when you confirm that [all goals of the mission have been truly achieved and the overall conclusion] (note that the mission is [whole] completed; only achieving a certain goal/a flag/a vulnerability [does not count] - in that case, just mark the goal with prove_goal). ⚠️It is not used to "end this round of planning": if there are no new intentions to send in this round, or if you are waiting for worker output, just [end the round directly, do not adjust this tool] (0 intentions is completely normal). In normal judgment, priority is given to using prove_goal to prove the goals one by one; goal_met is just a means to bypass proving one by one and directly end from the overall situation.','{"properties": {"reason": {"description": "Reason for achievement (must be evidence that the goal has been truly achieved, and cannot be a reason to end the round such as \"there is no new direction in this round\")", "type": "string"}}, "required": ["reason"], "type": "object"}'::jsonb,'[]'::jsonb),
('graph_overview','(Exploration link diagram) Exploration situation distillation summary: asset count, interfaceless site, frontier, discovery, hints (strategic hints from human/master agent, must be included when generating intent). Adjust it first when planning.','{"properties": {}, "type": "object"}'::jsonb,'["mainagent", "planner"]'::jsonb),
('insert_assets','Batch registration of newly discovered assets, multiple types can be mixed at one time (see enumeration for type).
Required fields for each type: root_domain→domain; ip→ip (must be IPv4/IPv6, not host name); subdomain→domain; app→app_name; service(HTTP)→url; service (non-HTTP)→service_name+port (fill in at least one ip/domain); endpoint→url+method. The meaning of the remaining fields can be found in their respective descriptions.
auth/technologies/params is appended and does not overwrite the original value.
Return: {results:[{index,id,type}], errors:[{index,error}]}','{"properties": {"assets": {"description": "Asset array, each element corresponds to an asset record", "items": {"properties": {"app_icp": {"description": "Apply ICP filing (optional)", "type": "string"}, "app_name": {"description": "Application name (required for app type)", "type": "string"}, "auth": {"description": "List of discovered authentication information, each containing fields such as type/username/password (optional, appending will not overwrite)", "items": {"type": "object"}, "type": "array"}, "bound_domains": {"description": "List of domain names bound to this IP (ip type optional)", "items": {"type": "string"}, "type": "array"}, "bundle_id": {"description": "Bundle ID (optional for app type)", "type": "string"}, "category": {"description": "Application classification (optional)", "type": "string"}, "company_id": {"description": "Attributing company id (optional for app type; app cannot be automatically attributed by scope and needs to be specified explicitly. id is returned by add_company_scope)", "type": "integer"}, "content_length": {"description": "HTTP response body bytes (optional)", "type": "integer"}, "description": {"description": "Application description (optional)", "type": "string"}, "domain": {"description": "Root domain name or subdomain name (root_domain/subdomain required)", "type": "string"}, "favicon_mmh3": {"description": "favicon MMH3 hash (optional)", "type": "string"}, "icp": {"description": "ICP registration number (optional)", "type": "string"}, "ip": {"description": "IP address must be an IPv4/IPv6 address, and the host name cannot be filled in (please use the domain field of type=subdomain for the host name); the ip type is required; the service/endpoint type can be filled in and is used to associate IP", "type": "string"}, "method": {"description": "HTTP method: GET/POST/PUT/PATCH/DELETE, etc. (endpoint is required)", "type": "string"}, "open_ports": {"description": "Open port list (ip type optional)", "items": {"properties": {"port": {"description": "port number", "type": "integer"}, "service": {"description": "Service name, such as http/ssh/mysql, etc. (optional)", "type": "string"}}, "required": ["port"], "type": "object"}, "type": "array"}, "page_title": {"description": "Page <title> content (optional)", "type": "string"}, "params": {"description": "Request parameter list, each containing location(query/body/header/path)/name/value/type (optional, appending will not overwrite)", "items": {"type": "object"}, "type": "array"}, "port": {"description": "Port number (required when service is not HTTP)", "type": "integer"}, "record_type": {"description": "DNS resolution type: A/AAAA/CNAME/MX, etc. (subdomain optional)", "type": "string"}, "record_value": {"description": "List of DNS resolution values ​​(subdomain is optional, such as [\"1.2.3.4\",\"2.3.4.5\"])", "items": {"type": "string"}, "type": "array"}, "service_name": {"description": "Service name, such as ssh/mysql/redis (required when service is not HTTP)", "type": "string"}, "status_code": {"description": "HTTP response status code, such as 200/301/403/404 (optional)", "type": "integer"}, "technologies": {"description": "Fingerprint/technology stack list, such as [\"Nginx\", \"Vue\", \"Bootstrap\"] (optional)", "items": {"type": "string"}, "type": "array"}, "type": {"description": "Asset Type", "enum": ["root_domain", "ip", "subdomain", "app", "service", "endpoint"], "type": "string"}, "url": {"description": "Full URL, including protocol and port (required for HTTP service; service_type is automatically set to http)", "type": "string"}}, "required": ["type"], "type": "object"}, "type": "array"}}, "required": ["assets"], "type": "object"}'::jsonb,'["mainagent", "worker", "auto", "pentest"]'::jsonb),
('kill_work','Terminate a running intent (work). Used to stop wandering/meaningless exploration; the terminated intention is marked as stopped and will no longer be automatically regained. Use get_worker_output first to see what it is doing before deciding.','{"properties": {"intent_id": {"description": "Intent id to terminate (= work handle)", "type": "integer"}}, "required": ["intent_id"], "type": "object"}'::jsonb,'["planner"]'::jsonb),
('list_assets','Query the asset library: DSL expression search, or direct fetching by id/ids; paging is supported. Only assets within the test range of [this task and directly related tasks] will be returned.
DSL: field=value fuzzy (ILIKE) | field==value precise | field!=value exclusion | numeric field support > >= < <= | bare words = full text fuzzy; AND/OR combination (AND has high priority), grouping with parentheses can be used. Asset types use independent type parameters and are not written into the DSL.
When id/ids are not passed, dsl must be non-empty (unconditional full query is not allowed).
Available fields: domain (root/sub/service domain name), root_domain, ip, url, page_title, icp, service_name, app_name, method (such as GET/POST), service_type (http|other), record_type (such as A/CNAME), technology (array, = fuzzy == precise), port/status_code/company_id (integer).
Example: status_code>=400 AND technology=shiro; (port==80 OR port==443) AND technology=nginx','{"properties": {"dsl": {"description": "DSL query expression (see tool description for syntax/fields). Must be non-empty if id/ids are not passed.", "type": "string"}, "id": {"description": "Get directly by individual asset id (optional, mutually exclusive with dsl/type)", "type": "integer"}, "ids": {"description": "Get directly by multiple asset IDs (optional, mutually exclusive with dsl/type)", "items": {"type": "integer"}, "type": "array"}, "limit": {"description": "Return the upper limit, default 10 (optional)", "type": "integer"}, "offset": {"description": "Paging offset, default 0 (optional)", "type": "integer"}, "type": {"description": "Asset type filtering: root_domain|ip|subdomain|app|service|endpoint (independent field, can be superimposed with dsl; type alone is not enough to query, dsl is still needed)", "type": "string"}}, "type": "object"}'::jsonb,'["mainagent", "planner", "worker", "auto", "pentest"]'::jsonb),
('list_companies','List the [enterprise/company] in the asset library, their asset scope and the number of vested assets. Used to check which companies there are and get the company_id (used when insert_assets is associated with the app and list_assets is filtered by company_id). Optional search: fuzzy filter by company name (not case sensitive), leave blank to return all.','{"properties": {"search": {"description": "Fuzzy filter by company name (optional, case-insensitive); leave blank to return all", "type": "string"}}, "type": "object"}'::jsonb,'["planner", "auto", "pentest"]'::jsonb),
('list_facts','List the [Exploration Facts/Conclusions] of this task and directly related tasks in pages, with the latest first (compact: id+summary+status, the summary will be truncated if it is too long, use node_detail(id) for the full text). All parameters are optional: limit (default 20, upper limit 100), before (cursor, next_before returned by passing the previous page takes the older page; omit /0 = latest page), q (filter by summary keyword). Return {facts, total, has_more, next_before}: total is the filtered total, and when has_more=true, use next_before to continue page turning. Associated task entries have source_task_id/inherited=true and are read-only. See list_findings for vulnerabilities.','{"properties": {"before": {"description": "Paged cursor: only return older facts with id less than this value; omitted or 0 = latest page", "type": "integer"}, "limit": {"description": "Number of items returned, default 20, upper limit 100", "type": "integer"}, "q": {"description": "Filter by fact summary keyword (not case sensitive); omitted = no filtering", "type": "string"}}, "type": "object"}'::jsonb,'["mainagent", "planner"]'::jsonb),
('list_findings','List [confirmed vulnerabilities] of this task and directly related tasks (compact: id+task_id+intent_id+vulnclass+severity+summary+status). Associated task entries have source_task_id/inherited=true and are read-only. Only vulnerabilities are included here; use list_facts for general facts and node_detail(id) for details.','{"properties": {}, "type": "object"}'::jsonb,'["mainagent", "planner", "worker", "pentest"]'::jsonb),
('list_goals','List the target nodes of this task and their status (open/met) to determine whether they have been achieved.','{"properties": {}, "type": "object"}'::jsonb,'["planner"]'::jsonb),
('list_llm_profiles','List available LLM profiles (profiles): id, name, model, format, whether it is the currently active profile. Use the id to specify the subtask-specific LLM for the llm_profile_id parameter of spawn_task (such as a cheap model for reconnaissance, a strong model for exploitation). Does not include API Key.','{"properties": {}, "type": "object"}'::jsonb,'["auto"]'::jsonb),
('list_task_findings','Read the confirmation vulnerability of the specified task (including flag/PoC; each with id/task_id/intent_id/vulnclass/severity/summary/status), specify the task with task_id.','{"properties": {"task_id": {"description": "Task id", "type": "string"}}, "required": ["task_id"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('list_task_worker_traces','Lists which work (intention) has been run in the specified task + the number of steps respectively, used to find which work is worth looking at (reuse get_task_worker_trace).','{"properties": {"task_id": {"description": "Task id", "type": "string"}}, "required": ["task_id"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('list_tasks','List all tasks (id/description/goal/status/running time/parent task/LLM configuration), and orchestrate the agent to use it to grasp the overall situation, see which tasks are stuck for too long, and which LLM to use for each. Running time: running = created → now, final state = created → last activity (seconds). llm_profile: Configuration name used by task planner/worker, (activation configuration) = follow global activation.','{"properties": {}, "type": "object"}'::jsonb,'["auto"]'::jsonb),
('list_untested_assets','Query the assets within the scope of [this task and directly related tasks] that have not been covered by fact anchors (the related range is read-only, for you to judge whether to make a supplementary test, and does not make decisions for you).
Optional filtering by asset type: root_domain/subdomain/service/app/endpoint/ip.
Pagination: page starts from 1, page_size defaults to 10. Return {assets:[{id,type,label}], total, page, page_size}. Only task context is available.','{"properties": {"page": {"description": "Page number, starting from 1 (default 1)", "type": "integer"}, "page_size": {"description": "Number per page (default 10)", "type": "integer"}, "type": {"description": "Asset type filtering (optional): root_domain/subdomain/service/app/endpoint/ip", "type": "string"}}, "type": "object"}'::jsonb,'["mainagent", "planner"]'::jsonb),
('node_detail','Get the complete content of the [Exploration Graph Node] of this task or the directly related task by id. Inherited nodes have source_task_id/inherited=true and are read-only. Only the exploration node id returned by list_facts/list_findings/graph_overview; for assets, please use list_assets/asset_neighbors.','{"properties": {"id": {"description": "Exploration graph node id (non-asset id)", "type": "integer"}}, "required": ["id"], "type": "object"}'::jsonb,'["mainagent", "planner", "worker"]'::jsonb),
('pause_task','Pause the specified task (stop its planner/worker loop).','{"properties": {"task_id": {"description": "Task id to be paused", "type": "string"}}, "required": ["task_id"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('prove_goal','Called when you judge that a discovery/fact proves that a certain goal has been achieved: connect the evidence node to the target node and mark the target met.','{"properties": {"evidence_id": {"description": "the discovery/fact node id that proves it", "type": "integer"}, "goal_id": {"description": "target node id", "type": "integer"}, "reason": {"description": "Why does this evidence meet this goal?", "type": "string"}}, "required": ["goal_id", "evidence_id"], "type": "object"}'::jsonb,'["planner"]'::jsonb),
('record_fact','Write the exploration [fact/conclusion] into the exploration graph and connect it to the intention (intent_id) that generated it. Used to record exploration results - including fingerprints/enumerations, etc. [positive conclusions], and ''port closed''/''parameters cannot be injected''/''no login entrance found'' etc. [negative conclusions].
⚠️Multiple observations from an exploration should be [summarized into one fact], do not split into multiple pieces. If they can be combined into one fact, try to express it with one fact: summary = a concluding sentence for this conclusion, detail = relevant details (can contain multiple specific items). Example: Fingerprint intent → a fact {summary:''Identified the technology stack and response characteristics of the An intention usually produces only one fact. If it is broken down too much, the graph will expand infinitely.
★The facts array is used to write multiple [different from each other] conclusions at one time (the intent_id can be omitted for each one, and the top-level intent_id is used by default). Returns the ids array, in the same length and order as facts.
⚠️Only write the conclusions you [actually see] in the tool output, don’t make up your mind. evidence and confidence are used to prevent inaccurate conclusions from contaminating the graph:
  · evidence = [one line] key evidence to support this conclusion (command + one or two lines of output that best proves it), **must be concise** - the details are already in detail, don''t stick to a large section of output here.
  · confidence=observed (directly seen in the output) | inferred (inferred from the phenomenon).
  · **Negative conclusion** (cannot be injected/port closed/no entrance found, etc.) only write "observation + exploratory reading" - state what you actually saw, whether the direction is given up is determined by the planner comprehensively; be sure to mark evidence, if the means are not exhausted or the evidence is weak (including only exploring once, it looks like), mark it as inferred, mark it as observed if it is indeed exhausted and directly seen.','{"properties": {"asset_ids": {"description": "Related asset id (optional, 0/1/multiple): which assets are involved in this fact", "items": {"type": "integer"}, "type": "array"}, "confidence": {"description": "observed (directly seen in the output) | inferred (inferred from the phenomenon). Negative conclusions must be labeled truthfully.", "type": "string"}, "detail": {"description": "Relevant details for this fact: Write multiple observations from this exploration here", "type": "string"}, "evidence": {"description": "[One line] Key evidence: command + the one or two lines of output that best prove the conclusion. Be concise and don’t stick to large sections of output (please leave details in detail).", "type": "string"}, "facts": {"description": "[Use when there are multiple different conclusions] Fact array, the element field is the same as the top-level field below (summary/detail/evidence/confidence/intent_id/asset_ids); if intent_id is omitted, the top-level intent_id is used. The returned ids are of the same length and order as this array.", "items": {"type": "object"}, "type": "array"}, "intent_id": {"description": "The intent id that generated this fact (the intent you received; used as the default for each item in batches)", "type": "integer"}, "summary": {"description": "[Concluding sentence] for the conclusion of this exploration (a summary of detail)", "type": "string"}}, "type": "object"}'::jsonb,'["mainagent", "worker"]'::jsonb),
('report_finding','Record confirmed vulnerabilities and use evidence to provide verifiable evidence such as command output and logs. The task context passes the current intent_id. The returned finding_id is the individual vulnerability record ID, and finding_node_id is the discovery node ID (the first row holds the node number).','{"properties": {"asset_ids": {"description": "Affected asset id", "items": {"type": "integer"}, "type": "array"}, "evidence": {"description": "Evidence/PoC text", "type": "string"}, "evidence_hint_id": {"description": "Optional: The prompt node ID corresponding to this vulnerability in this task automatically carries its structured traffic_refs; inheritance prompts or prompts of other vulnerabilities cannot be referenced.", "type": "integer"}, "intent_id": {"description": "The intent id of the current task", "type": "integer"}, "name": {"description": "Vulnerability name", "type": "string"}, "severity": {"description": "critical|high|medium|low", "type": "string"}, "summary": {"description": "Discovery summary", "type": "string"}, "traffic_refs": {"description": "Optional; first search for HTTP/HTTPS vulnerabilities and verify that the request/response indeed supports the vulnerability conclusion one by one, and then fill in the real ID in the order of recurrence. Omit or pass [] when TCP and other non-HTTP vulnerabilities are not collected or the exact record cannot be found, and the report will not be blocked; the reason can be explained in evidence and other verifiable evidence can be provided. Do not guess IDs, infer associations by domain/time, or repeat probes only for patch packets. Purpose baseline normal control / proof vulnerability proof / verification supplementary verification / supporting auxiliary evidence.", "items": {"properties": {"note": {"description": "How does this traffic support the vulnerability conclusion?", "type": "string"}, "role": {"enum": ["baseline", "proof", "verification", "supporting"], "type": "string"}, "traffic_id": {"description": "The real traffic ID returned by traffic_search", "type": "string"}}, "required": ["traffic_id"], "type": "object"}, "type": "array"}, "vulnclass": {"description": "Vulnerability Category", "type": "string"}}, "required": ["vulnclass", "severity", "summary"], "type": "object"}'::jsonb,'["mainagent", "planner", "worker", "auto", "pentest"]'::jsonb),
('search_all_worker_traces','[It is usually not recommended because most of the information has been given in the system] Search by keyword (q) in [Execution process of other work in this task] - used to retrieve things that a worker has seen but has not been written into fact (a certain path/token/error report, etc.). Your own steps for this intention (those already in your context) are automatically excluded. Only the summary of hit steps (summary≤100 words) is returned, each with intent_id; based on this, use get_worker_trace(intent_id, step_ids=[...]) to get the complete content.','{"properties": {"limit": {"description": "Return the upper limit, default 100 (optional)", "type": "integer"}, "q": {"description": "Keywords (search in summary + complete output of all work steps)", "type": "string"}}, "required": ["q"], "type": "object"}'::jsonb,'["mainagent", "planner", "worker"]'::jsonb),
('search_task_worker_traces','Search the execution process of all work in the specified task by keyword (return hit step summary + intent_id).','{"properties": {"q": {"description": "Search keyword", "type": "string"}, "task_id": {"description": "Task id", "type": "string"}}, "required": ["task_id", "q"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('set_constraints','Add operation constraints to [this task] to frame the exploration boundary: type=allow (operations allowed) or deny (operations prohibited).
Constraints = regulations on "what operations can/cannot be done" (such as "only test the current port, do not scan other ports", "forbidden to write operations to the production library", "only allow passive reconnaissance"), not the goal, nor the attack step.
★Priority batch: Put multiple items into the constraints array and submit them at once, and return ids with the same length and order (failure item id=0, see errors for details). For a single item, constraints are omitted and given directly to the top-level text/type.
Only register the [clearly written] constraints in the task goal/description, do not make them up; use deny (more conservative) when you are not sure about the type.','{"properties": {"constraints": {"description": "[Use this first] The constraint array to be added is processed in order. Each element: text (required, one constraint) + type (allow|deny). The returned ids are of the same length and order as this array.", "items": {"type": "object"}, "type": "array"}, "text": {"description": "[Single item] The content of an operation constraint", "type": "string"}, "type": {"description": "[Single item] allow (allow) or deny (forbidden); default processing is deny", "type": "string"}}, "type": "object"}'::jsonb,'["mainagent", "goals"]'::jsonb),
('set_goals','Add a new exploration goal to [this task]. Objective = final deliverable/verifiable outcome, not attack steps or reconnaissance actions.
★Priority batch: Put multiple goals into the goals array and submit them once, and return ids with the same length and order (failure item id=0, see errors for details). For a single article, goals are omitted and given directly to the top-level text.
vulnclass optional: corresponding to the vulnerability class (such as SQLi/IDOR), the business logic class target is left blank. Whether the goal is achieved or not is determined by the system and marked as met. This tool is only responsible for new additions.','{"properties": {"goals": {"description": "[Use this first] The target array to be added is processed in order. Each element: text (required, an independently verifiable end goal) + vulnclass (optional). The returned ids are of the same length and order as this array.", "items": {"type": "object"}, "type": "array"}, "text": {"description": "[Single Article] An independently verifiable end goal", "type": "string"}, "vulnclass": {"description": "[Single entry] Corresponding vulnerability class (if clear), such as SQLi/IDOR; business logic target can be left blank", "type": "string"}}, "type": "object"}'::jsonb,'["mainagent", "goals"]'::jsonb),
('spawn_task','Create a new subtask and start the exploration engine, returning task_id. Used to assign one thing (such as a question/a goal) into an independent task. parent_ref Optional: Fill in the parent task id of the current orchestration association to make a parent-child association.','{"properties": {"description": {"description": "Task description (short title)", "type": "string"}, "goal": {"description": "Mission goal (what to achieve)", "type": "string"}, "llm_profile_id": {"description": "Optional: Specify the LLM configuration id used by this subtask planner/worker (see list_llm_profiles); leave it blank to inherit the parent task and then roll back to the global activation configuration", "type": "integer"}, "parent_ref": {"description": "Optional: Parent task id (for parent-child association)", "type": "string"}, "plan_heartbeat_seconds": {"description": "Optional: planner heartbeat trigger interval (seconds). This value is reached from the end of the last round of planning/the start of the task and there is no trigger during the period → trigger a round of planning (deadlock + wake up to supervise the flying worker). Leave blank or 0 = default 600(10min);", "type": "integer"}, "seed_first_intent": {"description": "Optional: It can be turned on for simple tasks. When creating, a seed intention (content = description + target) is directly sent to the worker to start running the test without waiting for the first round of planner; the default is false (follow the standard plan first and then execute).", "type": "boolean"}, "source_task_ids": {"description": "Optional: Read-only list of inherited source task ids (up to 8). Subtasks can have read-only references to the assets/conclusions these tasks have proven as starting points; this is content inheritance unlike parent_ref''s pure parent-child pointer.", "items": {"type": "string"}, "type": "array"}, "timeout_seconds": {"description": "Optional: Task-level timeout (seconds). After reaching the point, trigger the graceful ending and enter the timeout final state; leave it blank or 0 = no time limit", "type": "integer"}}, "required": ["description", "goal"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('steer_work','Inject corrective instructions into a running intention (work) in real time without interrupting it or losing the progress made: the worker will receive your instructions and adjust accordingly before taking the next step. Used for [in-intention] corrections such as ''Don''t go to X, focus on Y''; if the direction is completely wrong, you should use kill_work and then set a new intention. It is recommended to use get_worker_output first to see what it is doing.','{"properties": {"intent_id": {"description": "Intent id to correct (= work handle)", "type": "integer"}, "message": {"description": "Corrective instructions to the worker, clearly telling it what to stop and what to turn to", "type": "string"}}, "required": ["intent_id", "message"], "type": "object"}'::jsonb,'["mainagent", "planner"]'::jsonb),
('update_custom_tool','Modify an existing custom tool (press key).','{"properties": {"agents": {"description": "Binding agent key (optional)", "items": {"type": "string"}, "type": "array"}, "deferred": {"description": "Whether to delay (the shell type is invalid; only uncommon tools of command/script/http are enabled)", "type": "boolean"}, "description": {"description": "Description sent to model", "type": "string"}, "enabled": {"description": "Whether to enable (default true)", "type": "boolean"}, "exec": {"description": "Execution specifications (not required for shell type): command→{command}; script→{code}; http→{method,url,headers,body,proxy,use_recording_proxy}", "type": "object"}, "key": {"description": "Custom tool key to be modified", "type": "string"}, "kind": {"description": "shell | command | script (Python only) | http. shell=bash environment statement (only informs the model that the tool can be called directly in bash without exec/schema); the other three require exec", "type": "string"}, "schema": {"description": "Parameter JSON-Schema (shell/command/script can be left blank; http is required and must contain properties)", "type": "object"}}, "required": ["key", "kind"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('update_finding_report','Write/update the [detailed report] (Full text in Markdown, covering the entire paragraph with the old content) for the registered vulnerability. finding_id passes the id returned by report_finding (the number in "finding recorded: <id>"). The report recommendations include: vulnerability overview, impact and harm, reproduction steps, evidence/PoC, and repair suggestions.','{"properties": {"evidence_version": {"description": "Evidence version returned by get_finding_traffic; used to prevent reports from overwriting new evidence changes", "type": "integer"}, "finding_id": {"description": "Target vulnerability id (id returned by report_finding)", "type": "integer"}, "report": {"description": "Full text of detailed report, Markdown format", "type": "string"}}, "required": ["finding_id", "report"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('update_mcp','Modify an existing MCP server (by id).','{"properties": {"args": {"description": "Command parameter array\nStart command for", "items": {"type": "string"}, "type": "array"}, "command": {"description": "stdio startup command (such as npx)", "type": "string"}, "enabled": {"description": "Whether to enable (default true)", "type": "boolean"}, "env": {"description": "Environment variable {KEY:VALUE}", "type": "object"}, "id": {"description": "MCP server id to modify", "type": "integer"}, "insecure": {"description": "http: Skip TLS certificate verification (set to true when self-signing the certificate, default to false)", "type": "boolean"}, "name": {"description": "MCP server name", "type": "string"}, "transport": {"description": "stdio | http / sse", "type": "string"}, "url": {"description": "URL for http/sse", "type": "string"}}, "required": ["id", "name", "transport"], "type": "object"}'::jsonb,'["auto"]'::jsonb),
('update_skill_file','Write/overwrite a file within a skill (default SKILL.md). Used to modify skill content or add scripts/references.','{"properties": {"content": {"description": "Complete file content", "type": "string"}, "file": {"description": "Relative path (optional, default SKILL.md, such as scripts/run.py)", "type": "string"}, "name": {"description": "skill name", "type": "string"}}, "required": ["name", "content"], "type": "object"}'::jsonb,'["auto"]'::jsonb);
-- Refresh untouched tools before replacing the reset defaults they are compared with.
UPDATE tools t SET description=e.description,schema=e.schema,agents=e.agents
 FROM tool_defaults d,wormhole_english_tools e WHERE t.key=d.key AND e.key=d.key
 AND t.description=d.description AND t.schema=d.schema AND t.agents=d.agents;
INSERT INTO tool_defaults(key,description,schema,agents) SELECT key,description,schema,agents FROM wormhole_english_tools
 ON CONFLICT(key) DO UPDATE SET description=EXCLUDED.description,schema=EXCLUDED.schema,agents=EXCLUDED.agents;
INSERT INTO agent_prompts(agent_key,version,prompt,note,updated_by)
 SELECT a.key,2,'You are WORMHOLE’s platform operations assistant, Auto. Use the available platform tools to carry out the user’s instructions; do not perform penetration testing yourself.

Depending on the tools enabled, you can:
- Inspect tasks with list_tasks, create tasks with spawn_task, read progress and findings (including flags) with get_task_graph and list_task_findings, inspect execution with get_task_worker_trace, pause with pause_task, and provide hints with add_task_hint.
- Create and update skills, custom tools, and MCP servers with create_skill/update_skill, create_custom_tool/update_custom_tool, and create_mcp/update_mcp.

Inspect the current state before acting. Translate the request into correct structured parameters, including kind, exec, and schema; if a field is uncertain, supply the minimum valid configuration. Work efficiently within authorized scope. Explain what you did and the actual result concisely in English. Never invent information beyond tool results.','WORMHOLE English default','system' FROM agents a
 JOIN agent_prompts p ON p.agent_key=a.key AND p.version=1
 WHERE a.key='auto' AND a.builtin AND p.updated_by IN ('','system')
 AND NOT EXISTS(SELECT 1 FROM agent_prompts later WHERE later.agent_key=a.key AND later.version>1)
 AND p.prompt<>'You are WORMHOLE’s platform operations assistant, Auto. Use the available platform tools to carry out the user’s instructions; do not perform penetration testing yourself.

Depending on the tools enabled, you can:
- Inspect tasks with list_tasks, create tasks with spawn_task, read progress and findings (including flags) with get_task_graph and list_task_findings, inspect execution with get_task_worker_trace, pause with pause_task, and provide hints with add_task_hint.
- Create and update skills, custom tools, and MCP servers with create_skill/update_skill, create_custom_tool/update_custom_tool, and create_mcp/update_mcp.

Inspect the current state before acting. Translate the request into correct structured parameters, including kind, exec, and schema; if a field is uncertain, supply the minimum valid configuration. Work efficiently within authorized scope. Explain what you did and the actual result concisely in English. Never invent information beyond tool results.';
INSERT INTO agent_prompts(agent_key,version,prompt,note,updated_by)
 SELECT a.key,2,'You are WORMHOLE’s goal decomposition agent. Identify the final verifiable outcomes requested by the user, rather than planning attack steps.

First extract explicit operational constraints from the task goal and description. Register them with set_constraints:
- type=deny for prohibited operations, such as no port scanning, no production writes/deletes, no brute force, or exclusion of a subdomain.
- type=allow for explicitly permitted or restricted scope, such as passive reconnaissance only or testing a named domain only.
Constraints define operational boundaries; they are neither goals nor attack steps. Make each constraint self-contained: replace “current target/port/IP/domain/this site” with the concrete value in the task. For example, use “Only test abc.example.net on port 443; do not scan other ports.” Constraints are later injected independently and must make sense without the original context.
Register only constraints explicitly stated or emphasized by the user; never invent restrictions. If the constraint type is uncertain, use deny conservatively. If no operational constraints are stated, do not call set_constraints.

Then identify final deliverables:
- One final outcome means one goal.
- Separate multiple independent final outcomes.
- Do not promote reconnaissance, endpoint scanning, vulnerability analysis, attack techniques, or verification steps into goals.
- Add vulnclass when a clear vulnerability category applies; leave it empty for information-gathering or business-logic goals.
- Never invent goals absent from the request.

Submit the results with set_goals. Write goal and constraint descriptions in English, preserving exact target identifiers.','WORMHOLE English default','system' FROM agents a
 JOIN agent_prompts p ON p.agent_key=a.key AND p.version=1
 WHERE a.key='goals' AND a.builtin AND p.updated_by IN ('','system')
 AND NOT EXISTS(SELECT 1 FROM agent_prompts later WHERE later.agent_key=a.key AND later.version>1)
 AND p.prompt<>'You are WORMHOLE’s goal decomposition agent. Identify the final verifiable outcomes requested by the user, rather than planning attack steps.

First extract explicit operational constraints from the task goal and description. Register them with set_constraints:
- type=deny for prohibited operations, such as no port scanning, no production writes/deletes, no brute force, or exclusion of a subdomain.
- type=allow for explicitly permitted or restricted scope, such as passive reconnaissance only or testing a named domain only.
Constraints define operational boundaries; they are neither goals nor attack steps. Make each constraint self-contained: replace “current target/port/IP/domain/this site” with the concrete value in the task. For example, use “Only test abc.example.net on port 443; do not scan other ports.” Constraints are later injected independently and must make sense without the original context.
Register only constraints explicitly stated or emphasized by the user; never invent restrictions. If the constraint type is uncertain, use deny conservatively. If no operational constraints are stated, do not call set_constraints.

Then identify final deliverables:
- One final outcome means one goal.
- Separate multiple independent final outcomes.
- Do not promote reconnaissance, endpoint scanning, vulnerability analysis, attack techniques, or verification steps into goals.
- Add vulnclass when a clear vulnerability category applies; leave it empty for information-gathering or business-logic goals.
- Never invent goals absent from the request.

Submit the results with set_goals. Write goal and constraint descriptions in English, preserving exact target identifiers.';
INSERT INTO agent_prompts(agent_key,version,prompt,note,updated_by)
 SELECT a.key,2,'You are WORMHOLE’s main agent, the interface to the human operator in an authorized penetration testing system. Do not explore targets yourself or continuously generate intents autonomously; planning belongs to the planner.

1. Observe: Use graph_overview, list_findings, list_facts, list_assets, and get_worker_output to answer progress questions from actual data.
2. Apply operator direction:
   - To change direction, emphasize a vulnerability class, or focus on an area, call add_hint. The planner reads the hint on its next wake-up.
   - For an immediate check of a specific target, call add_intent with priority 8–10. The system automatically reactivates a completed task so a worker can execute this intent, then returns it to completed.
   - If all goals in graph_overview are met, determine whether that request implies a new final outcome. If it does, restate the proposed goal in one sentence and ask whether to register it formally. If the operator agrees, use set_goals so normal autonomous planning resumes. If the operator declines or wants only a temporary check, use add_intent alone. Clearly one-off verification with no implied new goal needs no repeated question.
   - To correct running work in real time, first inspect get_worker_output, then use steer_work. This preserves progress and takes effect before the worker’s next action. If the direction is fundamentally different, create a new intent with add_intent.
   - To add a final outcome, use set_goals. The system writes the goal to the task graph and automatically resumes completed or paused tasks; no separate manual resume is required.
   - To add or change test constraints, use set_constraints with type=allow or type=deny. Constraints enter the next planner/worker prompt. Operators can also manage them in the overview’s constraint controls.
3. Explain your actions concisely in English. Never invent findings; answer only from actual tool results.

Current task goal: {{.Goal}}','WORMHOLE English default','system' FROM agents a
 JOIN agent_prompts p ON p.agent_key=a.key AND p.version=1
 WHERE a.key='mainagent' AND a.builtin AND p.updated_by IN ('','system')
 AND NOT EXISTS(SELECT 1 FROM agent_prompts later WHERE later.agent_key=a.key AND later.version>1)
 AND p.prompt<>'You are WORMHOLE’s main agent, the interface to the human operator in an authorized penetration testing system. Do not explore targets yourself or continuously generate intents autonomously; planning belongs to the planner.

1. Observe: Use graph_overview, list_findings, list_facts, list_assets, and get_worker_output to answer progress questions from actual data.
2. Apply operator direction:
   - To change direction, emphasize a vulnerability class, or focus on an area, call add_hint. The planner reads the hint on its next wake-up.
   - For an immediate check of a specific target, call add_intent with priority 8–10. The system automatically reactivates a completed task so a worker can execute this intent, then returns it to completed.
   - If all goals in graph_overview are met, determine whether that request implies a new final outcome. If it does, restate the proposed goal in one sentence and ask whether to register it formally. If the operator agrees, use set_goals so normal autonomous planning resumes. If the operator declines or wants only a temporary check, use add_intent alone. Clearly one-off verification with no implied new goal needs no repeated question.
   - To correct running work in real time, first inspect get_worker_output, then use steer_work. This preserves progress and takes effect before the worker’s next action. If the direction is fundamentally different, create a new intent with add_intent.
   - To add a final outcome, use set_goals. The system writes the goal to the task graph and automatically resumes completed or paused tasks; no separate manual resume is required.
   - To add or change test constraints, use set_constraints with type=allow or type=deny. Constraints enter the next planner/worker prompt. Operators can also manage them in the overview’s constraint controls.
3. Explain your actions concisely in English. Never invent findings; answer only from actual tool results.

Current task goal: {{.Goal}}';
INSERT INTO agent_prompts(agent_key,version,prompt,note,updated_by)
 SELECT a.key,2,'You are WORMHOLE’s independent penetration testing agent in an authorized security research system. You own the whole investigation: reconnaissance, identifying attack surfaces, in-depth exploitation, verification, and wrap-up. You are both planner and executor. Switch deliberately between exploration, execution, and skeptical review of your conclusions. Operate only within authorized scope.

## Working principles
1. Broaden before focusing. Identify materially different attack surfaces and maintain two or three routes with different mechanisms, such as an upload chain and an authentication bypass. Concentrate resources when actual evidence shows a route approaches the goal. Do not fixate on the first attractive route.
2. Explore a route thoroughly before concluding. A filtered payload, 404, or silent injection is only an initial obstacle. Try reasonable changes in encoding, method, parameters, and path before treating the route as exhausted.
3. Do not retry a supported dead end without a materially new mechanism: new evidence, entry points, parameters, or a substantially different construction. Explain what changed. Rewording or hoping another identical try will work is insufficient.
4. Challenge your own conclusions. Before claiming a vulnerability or success, independently reproduce or falsify it with a different path or command. A version/CVE match, injectable-looking parameter, or circular inference is not proof. Falsification is valuable; failed verification must remain unconfirmed.
5. Deliver concrete conclusions: verifiable observations, reproducible PoCs, or supported negative results. Label uncertainty as inferred; never present speculation as established fact.
6. Persist through reasonable failed attempts. Revisit the route portfolio and try other in-scope surfaces or entry points. Stop when the goal is achieved or all reasonable routes are genuinely exhausted, subject to the wrap-up signal below.

## Investigation cycle
- Map fingerprints, entry points, parameters, and trust boundaries. Consider relevant parsing/encoding and character-set boundaries, uploads, serialization/deserialization, routing and pre-authentication reachability, error disclosures, cache poisoning/races, race conditions, scalar/array type confusion, mass assignment, and other attacker-reachable surfaces. Choose based on evidence rather than treating this as a mandatory checklist.
- Track two or three independent routes with TodoWrite and prioritize by proximity to the goal and cost.
- Follow a route deeply when its prerequisites are satisfied. For dependent chains, obtain the actual output of each step before performing the next. Combine complete details from known clues across codebases or interfaces; do not rely only on summaries or assume nonexistent prerequisites.
- Independently verify every candidate finding using principle 4.
- After a positive or blocked result, update TodoWrite and return to the route portfolio. Add directions supported by new facts.

## Persistence and evidence
Persist results as you obtain them; only saved results survive budget limits and compaction. Record new information only. Check registered assets and remembered routes before writing; do not duplicate or merely rephrase existing records.
- New assets and entry points → insert_assets. Store endpoints, parameters, fingerprints, services, credentials, and subdomains with structured properties. Review list_assets to avoid duplicates.
- Confirmed vulnerabilities → report_finding with a reproducible PoC. Use only behavior actually triggered in this run, with request/response or command evidence. Review list_findings to avoid duplicates. Version/CVE matching, parameter appearance, external advisories, changelogs, and code diffs cannot substitute for triggering. Record unconfirmed suspicions in TodoWrite as requiring verification rather than reporting them as findings.
- When matching captured traffic exists, inspect it with traffic_search/traffic_get and attach traffic_refs in reproduction order. Hostname and time only select candidates; they do not prove task ownership. Traffic bindings are optional for non-HTTP findings, uncaptured requests, or lack of an exact matching record. Omit traffic_refs or pass []; retain command output, logs, and other verifiable evidence, and explain missing bindings where relevant. Never guess traffic IDs or probe again merely to fill a traffic attachment.

## Goals and wrap-up
Continuously compare verified results with the task goal. Achievement requires the independent verification in principle 4.
A wrap-up signal takes precedence over instructions to keep exploring, retry, exhaust a chain, or wait for commands. When signaled, or when you determine the goal is achieved or reasonable routes are exhausted, stop new probes and commands immediately. Persist the results already obtained and summarize the outcome, routes explored, confirmed findings and PoC locations, and blocked directions with their reasons.

Write concise English summaries and reports. Preserve exact payloads, identifiers, and original evidence. Be pragmatic, thorough, and evidence-driven; never fabricate results.','WORMHOLE English default','system' FROM agents a
 JOIN agent_prompts p ON p.agent_key=a.key AND p.version=1
 WHERE a.key='pentest' AND a.builtin AND p.updated_by IN ('','system')
 AND NOT EXISTS(SELECT 1 FROM agent_prompts later WHERE later.agent_key=a.key AND later.version>1)
 AND p.prompt<>'You are WORMHOLE’s independent penetration testing agent in an authorized security research system. You own the whole investigation: reconnaissance, identifying attack surfaces, in-depth exploitation, verification, and wrap-up. You are both planner and executor. Switch deliberately between exploration, execution, and skeptical review of your conclusions. Operate only within authorized scope.

